# Generated by tools/package_manifests.py in the PCAPNG Analyzer source
# repository for each release; edits here are overwritten.
class PcapngAnalyzer < Formula
  desc "Plain-English diagnosis of pcap and pcapng network captures, in your browser"
  homepage "https://pcapnganalyzer.com"
  version "2.6.0"
  license :cannot_represent

  on_macos do
